SELECT ksva.id `id`, ks.`name` `studentName`, kc.class_name FROM kg_student_vacate_apply ksva LEFT JOIN kg_student ks ON ksva.student_id = ks.id LEFT JOIN kg_classroom kc ON kc.id = ks.class_id WHERE ksva.del_flag = 0 AND ks.del_flag = 0 AND ksva.kg_id = #{queryVO.kgId} AND ksva.status = 0
AND kc.id = #{queryVO.classroomId}
ORDER BY ksva.id DESC

SELECT student_id 'studentId', type 'vacateType' FROM kg_student_vacate_apply ksva WHERE ksva.STATUS = #{queryVO.status} AND ksva.del_flag = 0 AND ksva.kg_id = #{queryVO.kgId} AND ksva.student_id IN
#{item}
AND ( DATE_FORMAT(ksva.begin_time,'%Y-%m-%d') <= #{queryVO.date} AND DATE_FORMAT(ksva.end_time,'%Y-%m-%d') >= #{queryVO.date} )

select student_id 'studentId', type 'vacateType', begin_time 'beginTime', end_time 'endTime' from kg_student_vacate_apply ksva where ksva.status = #{queryVO.status} and kg_id = #{queryVO.kgId} and ksva.student_id in
#{item}
and ( #{queryVO.minDate}<=DATE_FORMAT(ksva.end_time,'%Y-%m-%d') and #{queryVO.maxDate}>=DATE_FORMAT(ksva.begin_time,'%Y-%m-%d')) or(#{queryVO.minDate}>DATE_FORMAT(ksva.end_time,'%Y-%m-%d') and #{queryVO.maxDate}<DATE_FORMAT(ksva.begin_time,'%Y-%m-%d'))

