or(#{queryVO.first}>DATE_FORMAT(end_time,'%Y-%m-%d') and #{queryVO.last}<DATE_FORMAT(begin_time,'%Y-%m-%d'))

SELECT id, bloc_id, kg_id, student_id, type, begin_time, end_time, reason, approve_by, approve_time, approve_opinion, `STATUS`, create_by, create_time, update_by, update_time, del_flag FROM kg_student_vacate_apply WHERE DATE_FORMAT( begin_time, '%Y-%m-%d' ) <= #{beginDate} AND DATE_FORMAT( end_time, '%Y-%m-%d' ) >= #{endDate} AND `status` = 1 AND student_id IN (
